-- ═══════════════════════════════════════════════════════
-- Phase 2: Class descriptions
-- ═══════════════════════════════════════════════════════
UPDATE classes SET description_es='Los bárbaros son guerreros primitivos de gran fortaleza. Su poder nace de una furia interior que les otorga resistencia sobrehumana en combate. Conocedores de tierras salvajes, su rabia los convierte en máquinas de destrucción imparables.', description_gl='Os bárbaros son guerreiros primitivos de gran fortaleza. O seu poder nace dunha rabia interior que lles outorga resistencia sobrehumana no combate. Coñecedores de terras salvaxes, a súa ira convérteos en máquinas de destrución imparables.' WHERE index_name='barbarian';
UPDATE classes SET description_es='Los bardos tejen la magia a través de palabras y música. Son artistas, narradores y maestros del conocimiento que inspiran a sus aliados y desconciertan a sus enemigos con sus proezas arcanas.', description_gl='Os bardos tecen a maxia a través de palabras e música. Son artistas, narradores e mestres do coñecemento que inspiran aos seus aliados e desconcertan aos seus inimigos coas súas proezas arcanas.' WHERE index_name='bard';
UPDATE classes SET description_es='Los clérigos son intermediarios entre el mundo mortal y los planos divinos. Empuñan el poder de su deidad para curar, proteger y destruir en nombre de su fe.', description_gl='Os clérigos son intermediarios entre o mundo mortal e os planos divinos. Embrandan o poder da súa deidade para curar, protexer e destruír en nome da súa fe.' WHERE index_name='cleric';
UPDATE classes SET description_es='Los druidas encarnan la fuerza de la naturaleza. Pueden adoptar formas animales y lanzar hechizos vinculados a los elementos. Son guardianes del equilibrio natural del mundo.', description_gl='Os druídas encarnan a forza da natureza. Poden adoptar formas animais e lanzar feitizos vinculados aos elementos. Son gardiáns do equilibrio natural do mundo.' WHERE index_name='druid';
UPDATE classes SET description_es='Los guerreros son maestros del combate con armas y armaduras. Aprenden diversas técnicas de lucha y pueden adoptar especializaciones marciales que los hacen letales en el campo de batalla.', description_gl='Os guerreiros son mestres do combate con armas e armazóns. Aprenden diversas técnicas de loita e poden adoptar especializacións marciais que os fan letais no campo de batalla.' WHERE index_name='fighter';
UPDATE classes SET description_es='Los monjes aprovechan la energía que fluye en sus cuerpos. A través del entrenamiento austero, dominan el ki —la fuerza mística— para superar los límites físicos y enfrentarse al enemigo a manos vacías.', description_gl='Os monxes aproveitan a enerxía que flúe nos seus corpos. A través do adestramento austero, dominan o ki —a forza mística— para superar os límites físicos e enfrontarse ao inimigo a mans baleiras.' WHERE index_name='monk';
UPDATE classes SET description_es='Los paladines son guerreros sagrados que juran defender los ideales de justicia y bien. Combinan el poder de combate con hechizos divinos y auras que refuerzan a sus compañeros.', description_gl='Os paladinos son guerreiros sagrados que xuran defender os ideais de xustiza e ben. Combinan o poder de combate con feitizos divinos e auras que reforzan aos seus compañeiros.' WHERE index_name='paladin';
UPDATE classes SET description_es='Los exploradores son cazadores y rastreadores de tierras salvajes. Dominan el combate en la naturaleza, tienen aliados animales y hechizos ligados al mundo natural.', description_gl='Os exploradores son cazadores e rastrexadores de terras salvaxes. Dominan o combate na natureza, teñen aliados animais e feitizos ligados ao mundo natural.' WHERE index_name='ranger';
UPDATE classes SET description_es='Los pícaros confían en la astucia, el sigilo y la habilidad para vencer. Son expertos en el ataque sorpresa, con un talento especial para explorar, desactivar trampas y actuar en las sombras.', description_gl='Os pícaros confían na astucia, o sixilo e a habilidade para vencer. Son expertos no ataque sorpresa, cun talento especial para explorar, desactivar trampas e actuar nas sombras.' WHERE index_name='rogue';
UPDATE classes SET description_es='Los hechiceros poseen un poder mágico innato, fruto de su linaje o de una influencia sobrenatural. Canalizan la magia de forma instintiva sin necesidad de largos estudios.', description_gl='Os feiticeiros posúen un poder máxico innato, froito do seu liñaxe ou dunha influencia sobrenatural. Canalizan a maxia de forma instintiva sen necesidade de longos estudos.' WHERE index_name='sorcerer';
UPDATE classes SET description_es='Los brujos obtienen su poder de un pacto con un ser sobrenatural. Acceden a una magia oscura y poderosa a cambio de servir los intereses de su patrón.', description_gl='Os bruxos obteñen o seu poder dun pacto cun ser sobrenatural. Acceden a unha maxia escura e poderosa a cambio de servir os intereses do seu patrón.' WHERE index_name='warlock';
UPDATE classes SET description_es='Los magos son el epítome del usuario de magia, definidos por los hechizos que lanzan. Aprenden la magia a través del estudio riguroso y pueden lanzar hechizos de una variedad casi ilimitada.', description_gl='Os magos son o epítome do usuario de maxia, definidos polos feitizos que lanzan. Aprenden a maxia a través do estudo rigoroso e poden lanzar feitizos dunha variedade case ilimitada.' WHERE index_name='wizard';

-- ═══════════════════════════════════════════════════════
-- Phase 2: Subrace descriptions
-- ═══════════════════════════════════════════════════════
UPDATE subraces SET description_es='Descendiente de una antigua subespecie de elfos de piel oscura, los drow fueron desterrados del mundo de la superficie. Viven en las profundidades del Infraoscuridad y adoran a la diosa Lolth.', description_gl='Descendente dunha antiga subespecies de elfos de pel escura, os drow foron desterrados do mundo da superficie. Viven nas profundidades do Infraescuridade e adoran á deusa Lolth.' WHERE index_name='drow';
UPDATE subraces SET description_es='Como gnomo del bosque, posees un talento natural para la ilusión y una rapidez y sigilo inherentes. Los gnomos del bosque son raros y secretivos.', description_gl='Como gnomo do bosque, posúes un talento natural para a ilusión e unha rapidez e sixilo inherentes. Os gnomos do bosque son raros e secretivos.' WHERE index_name='forest-gnome';
UPDATE subraces SET description_es='Como elfo de las alturas, posees una mente aguda y dominas al menos los conceptos básicos de la magia.', description_gl='Como elfo das alturas, posúes unha mente aguda e dominas polo menos os conceptos básicos da maxia.' WHERE index_name='high-elf';
UPDATE subraces SET description_es='Como enano de las colinas, posees sentidos agudos, una profunda intuición y una notable resistencia.', description_gl='Como anano das colinas, posúes sentidos agudos, unha profunda intuición e unha notable resistencia.' WHERE index_name='hill-dwarf';
UPDATE subraces SET description_es='Como mediano a pie ligero, puedes ocultarte fácilmente de la vista, incluso usando otras personas como cobertura. Eres afable y te llevas bien con todos.', description_gl='Como halfling a pé lixeiro, podes ocultarte facilmente da vista, incluso usando outras persoas como cobertura. Es afable e lévaste ben con todos.' WHERE index_name='lightfoot-halfling';
UPDATE subraces SET description_es='Como enano de la montaña, eres fuerte y resistente, acostumbrado a una vida difícil en terreno accidentado.', description_gl='Como anano da montaña, es forte e resistente, afeito a unha vida difícil en terreo accidentado.' WHERE index_name='mountain-dwarf';
UPDATE subraces SET description_es='Como gnomo de las rocas, posees una inventiva natural y una resistencia superior a la de otros gnomos.', description_gl='Como gnomo das rochas, posúes unha inventiva natural e unha resistencia superior á doutros gnomos.' WHERE index_name='rock-gnome';
UPDATE subraces SET description_es='Como mediano robusto, eres más resistente que la media y tienes cierta resistencia al veneno.', description_gl='Como halfling robusto, es máis resistente que a media e tes certa resistencia ao veleno.' WHERE index_name='stout-halfling';
UPDATE subraces SET description_es='Como elfo del bosque, posees sentidos e intuición agudos, y tus ágiles pies te llevan rápida y sigilosamente por tus bosques natales.', description_gl='Como elfo do bosque, posúes sentidos e intuición agudos, e os teus ágiles pés lévante rápida e sixilosamente polos teus bosques natais.' WHERE index_name='wood-elf';

